vulnerable_code:
router.post('/auth/token/rotate', async (req, res) => {
  const { tokenHash, accountId } = req.body;

  const existing = await knex('refresh_tokens')
    .where({ token_hash: tokenHash })
    .first();

  if (!existing || existing.revoked) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  const newHash = crypto.randomBytes(32).toString('hex');
  await knex('refresh_tokens').insert({
    account_id: accountId,
    token_hash: newHash,
    created_at: new Date()
  });
  await knex('refresh_tokens').where({ id: existing.id }).update({ revoked: true });

  res.json({ newRefreshToken: newHash, accountId });
});

corrected_code:
router.post('/auth/token/rotate', async (req, res) => {
  const { tokenHash } = req.body;

  const existing = await knex('refresh_tokens')
    .where({ token_hash: tokenHash })
    .first();

  if (!existing || existing.revoked) {
    return res.status(401).json({ error: 'Invalid token' });
  }

  const newHash = crypto.randomBytes(32).toString('hex');
  await knex('refresh_tokens').insert({
    account_id: existing.account_id,
    token_hash: newHash,
    created_at: new Date()
  });
  await knex('refresh_tokens').where({ id: existing.id }).update({ revoked: true });

  res.json({ newRefreshToken: newHash, accountId: existing.account_id });
});
